package com.ecole.gestion_scolaire.registration.service; import com.ecole.gestion_scolaire.common.dto.PageResponse; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.entity.*; import com.ecole.gestion_scolaire.registration.enums.*; import com.ecole.gestion_scolaire.registration.exception.RegistrationValidationException; import com.ecole.gestion_scolaire.registration.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate;
@Service @Transactional(readOnly=true) public class StudentEnrollmentService {private final StudentEnrollmentRepository repo;private final EnrollmentClassHistoryRepository history;private final RegistrationReferenceValidator refs;public StudentEnrollmentService(StudentEnrollmentRepository r,EnrollmentClassHistoryRepository h,RegistrationReferenceValidator refs){repo=r;history=h;this.refs=refs;}public StudentEnrollmentResponse findByStudentAndYear(Long s,Long y){return repo.findByStudentIdAndSchoolYearId(s,y).map(this::map).orElse(null);}public PageResponse<StudentEnrollmentResponse> byYear(Long y,int page,int size){page=Math.max(0,page);size=Math.min(Math.max(1,size),100);return PageResponse.from(repo.findBySchoolYearId(y,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"))).map(this::map));}
 @Transactional public StudentEnrollmentResponse createFromRegistration(RegistrationCase c,StudentEnrollmentCreateRequest r){if(repo.existsByStudentIdAndSchoolYearId(c.getStudent().getId(),c.getSchoolYearId()))throw new RegistrationValidationException("L’élève est déjà scolarisé pour cette année.");refs.classGroup(r.classGroupId());refs.classMatches(r.classGroupId(),c.getSchoolYearId(),c.getRequestedLevelId());var e=new StudentEnrollment();e.setStudent(c.getStudent());e.setSchoolYearId(c.getSchoolYearId());e.setCurrentClassGroupId(r.classGroupId());e.setEnrollmentDate(r.enrollmentDate()==null?LocalDate.now():r.enrollmentDate());e.setEntryType(r.entryType());e.setStatus(EnrollmentStatus.ACTIVE);e=repo.save(e);var h=new EnrollmentClassHistory();h.setEnrollment(e);h.setClassGroupId(r.classGroupId());h.setStartDate(e.getEnrollmentDate());h.setReason("INSCRIPTION_INITIALE");history.save(h);return map(e);}
 @Transactional public StudentEnrollmentResponse changeClass(Long id,ClassChangeRequest r){var e=repo.findById(id).orElseThrow(()->new RegistrationValidationException("Scolarisation introuvable : "+id));refs.classGroup(r.classGroupId());LocalDate d=r.effectiveDate()==null?LocalDate.now():r.effectiveDate();var list=history.findByEnrollmentIdOrderByStartDateAsc(id);list.stream().filter(h->h.getEndDate()==null).forEach(h->{h.setEndDate(d.minusDays(1));history.save(h);});e.setCurrentClassGroupId(r.classGroupId());repo.save(e);var h=new EnrollmentClassHistory();h.setEnrollment(e);h.setClassGroupId(r.classGroupId());h.setStartDate(d);h.setReason(r.reason());history.save(h);return map(e);}public StudentEnrollmentResponse map(StudentEnrollment e){return new StudentEnrollmentResponse(e.getId(),e.getStudent().getId(),e.getStudent().getStudentNumber(),e.getSchoolYearId(),e.getCurrentClassGroupId(),e.getEnrollmentDate(),e.getEntryType(),e.getStatus(),e.getExitDate(),e.getExitReason(),e.getCreatedAt(),e.getUpdatedAt());}}
